<?php
if (isset($_SERVER['SCRIPT_FILENAME']) && basename((string)$_SERVER['SCRIPT_FILENAME']) === 'he-vault.php') {
  http_response_code(404);
  header('Content-Type: text/plain; charset=utf-8');
  exit;
}
function he_vault_open($keyB64) {
  if (!function_exists('openssl_decrypt')) return '';
  $key = base64_decode((string)$keyB64, true);
  if ($key === false || strlen($key) !== 32) return '';
  $raw = base64_decode(he_vault_blob(), true);
  if ($raw === false || strlen($raw) < 29) return '';
  $iv = substr($raw, 0, 12);
  $tag = substr($raw, -16);
  $ct = substr($raw, 12, -16);
  $pt = openssl_decrypt($ct, 'aes-256-gcm', $key, OPENSSL_RAW_DATA, $iv, $tag);
  return is_string($pt) ? $pt : '';
}
function he_vault_blob() {
  return '';
}
